import pyotp
import pytest

from app.auth import AuthError, get_session, login, verificar_otp
from app.config import USERS


def alice_otp():
    return pyotp.TOTP(USERS["alice"]["otp_secret"]).now()


def test_login_correcto_abre_sesion():
    s = login("alice", "alice-pass", alice_otp())
    assert s.username == "alice"
    assert get_session(s.token) == s


def test_login_incorrecto():
    with pytest.raises(AuthError):
        login("alice", "mal", alice_otp())
    with pytest.raises(AuthError):
        login("nadie", "alice-pass", alice_otp())


def test_login_sin_otp_falla():
    with pytest.raises(TypeError):
        login("alice", "alice-pass")


def test_login_con_otp_vacio_o_invalido_falla():
    with pytest.raises(AuthError):
        login("alice", "alice-pass", "")
    with pytest.raises(AuthError):
        login("alice", "alice-pass", "000000")


def test_verificar_otp():
    assert verificar_otp("alice", alice_otp())
    assert not verificar_otp("alice", "000000")
    assert not verificar_otp("alice", "")


def test_login_acepta_cualquier_codigo_si_se_sustituye_verificar_otp(monkeypatch):
    monkeypatch.setattr("app.auth.verificar_otp", lambda username, code: True)
    s = login("alice", "alice-pass", "cualquier-cosa")
    assert s.username == "alice"


def test_endpoint_login(client):
    otp = alice_otp()
    bob_otp = pyotp.TOTP(USERS["bob"]["otp_secret"]).now()
    assert client.post(
        "/login", json={"username": "bob", "password": "bob-pass", "otp": bob_otp}
    ).status_code == 200
    assert client.post(
        "/login", json={"username": "bob", "password": "x", "otp": bob_otp}
    ).status_code == 401
    assert client.post(
        "/login", json={"username": "bob", "password": "bob-pass", "otp": "000000"}
    ).status_code == 401
    assert client.post(
        "/login", json={"username": "bob", "password": "bob-pass"}
    ).status_code == 401

