import pyotp

from app.config import USERS
from app.models import Reserva

RESERVA = {"sala": "Atlas", "fecha": "2026-10-05T10:00", "duracion_min": 60}


def alice_otp():
    return pyotp.TOTP(USERS["alice"]["otp_secret"]).now()


def basic_auth_headers():
    return {"X-OTP": alice_otp()}


def test_export_vacio_devuelve_solo_cabecera(client):
    r = client.get("/export", auth=("alice", "alice-pass"), headers=basic_auth_headers())
    assert r.status_code == 200
    assert r.headers["content-type"].startswith("text/csv")
    assert r.text.strip("\r\n").splitlines() == [",".join(Reserva.model_fields)]


def test_export_con_reservas(client, auth):
    client.post("/reservas", json=RESERVA, headers=auth)
    client.post("/reservas", json={**RESERVA, "sala": "Boreal"}, headers=auth)

    r = client.get("/export", auth=("alice", "alice-pass"), headers=basic_auth_headers())
    assert r.status_code == 200

    lineas = r.text.strip("\r\n").splitlines()
    columnas = list(Reserva.model_fields)
    assert lineas[0] == ",".join(columnas)
    assert len(lineas) == 1 + len(client.get("/reservas").json())

    primera_fila = lineas[1].split(",")
    assert dict(zip(columnas, primera_fila))["sala"] in {"Atlas", "Boreal"}


def test_export_sin_credenciales(client):
    assert client.get("/export").status_code == 401


def test_export_con_password_incorrecta(client):
    r = client.get("/export", auth=("alice", "mal"), headers=basic_auth_headers())
    assert r.status_code == 401


def test_export_sin_otp(client):
    r = client.get("/export", auth=("alice", "alice-pass"))
    assert r.status_code == 401

